import{_ as d,o as r,c as e,a2 as o}from"./chunks/framework.CCXDMzJr.js";const p=JSON.parse('{"title":"附录 B 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix-b-glossary.md","filePath":"appendix-b-glossary.md","lastUpdated":null}'),s={name:"appendix-b-glossary.md"};function n(a,t,g,i,l,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="附录-b-术语表" tabindex="-1">附录 B 术语表 <a class="header-anchor" href="#附录-b-术语表" aria-label="Permalink to &quot;附录 B 术语表&quot;">​</a></h1><h2 id="框架层" tabindex="-1">框架层 <a class="header-anchor" href="#框架层" aria-label="Permalink to &quot;框架层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>释义</th></tr></thead><tbody><tr><td><strong>Cordis</strong></td><td>dsh 底层的插件框架（vendored 于 <code>vendor/cordis</code>）：服务、事件、可逆副作用</td></tr><tr><td><strong>Context（ctx）</strong></td><td>服务的仓库；一个代理对象，属性读取即服务解析</td></tr><tr><td><strong>Service</strong></td><td>挂到 <code>ctx.&lt;key&gt;</code> 上的能力；构造即注册、fiber 卸载即消失</td></tr><tr><td><strong>Plugin</strong></td><td>函数/类/对象三种形态的插件入口；<code>apply(ctx, config)</code> 为共同执行体</td></tr><tr><td><strong>Fiber</strong></td><td>一枚插件的一次装载；PENDING/LOADING/ACTIVE/FAILED/UNLOADING/DISPOSED 状态机</td></tr><tr><td><strong>inject</strong></td><td>插件声明的硬依赖；依赖就绪才装载，消失即卸载</td></tr><tr><td><strong>effect</strong></td><td>可逆副作用容器；卸载时逆序清理 disposer</td></tr><tr><td><strong>isolate</strong></td><td>服务隔离作用域：同标签内提供独立实现，标签外不可见</td></tr><tr><td><strong>intercept</strong></td><td>服务配置拦截：子 context 的插件看到合并后的配置</td></tr><tr><td><strong>emit / parallel / serial / bail / waterfall</strong></td><td>五种事件派发模式：观察 / 扇出等待 / 串行决策 / 同步决策 / 洋葱中间件</td></tr><tr><td><strong>waterfall next()</strong></td><td>中间件委派；不调用 next() 即否决</td></tr></tbody></table><h2 id="运行层" tabindex="-1">运行层 <a class="header-anchor" href="#运行层" aria-label="Permalink to &quot;运行层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>释义</th></tr></thead><tbody><tr><td><strong>Profile（配置档）</strong></td><td>命名组合：bundles 列表 + 用户 patch；<code>web</code>/<code>headless</code> 为内置模板</td></tr><tr><td><strong>Bundle（捆绑包）</strong></td><td>配置行 + 代码的分发格式；<code>dsh-base</code>/<code>dsh-web-app</code>/<code>dsh-headless</code> 三种内置</td></tr><tr><td><strong>Patch（补丁）</strong></td><td>按 id 整行替换或 insert 新行的组合修改</td></tr><tr><td><strong>Host / Client</strong></td><td>Node 进程侧 / 浏览器侧两棵 Cordis 树</td></tr><tr><td><strong>agent preset</strong></td><td>单个会话的能力组合（<code>~/.dsh/.agent-presets/&lt;id&gt;/</code>）</td></tr><tr><td><strong>isolate realm</strong></td><td>preset 内一组行共享的隔离服务作用域（<code>cordis:group</code>）</td></tr><tr><td><strong>seam（能力接缝）</strong></td><td>定义 + 提供者 + 消费者三件套的可替换能力</td></tr></tbody></table><h2 id="会话与-agent" tabindex="-1">会话与 Agent <a class="header-anchor" href="#会话与-agent" aria-label="Permalink to &quot;会话与 Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>释义</th></tr></thead><tbody><tr><td><strong>Session（会话）</strong></td><td>追加型 <code>SessionEvent</code> 日志；模型历史的唯一派生源</td></tr><tr><td><strong>SessionEvent</strong></td><td>一条日志条目：<code>{type, seq, time, data}</code>，写入时深冻结</td></tr><tr><td><strong>Surface</strong></td><td>三种消息产生型事件的派生表面；<code>replace</code> 是压缩机制</td></tr><tr><td><strong>deriveMessages()</strong></td><td>从日志派生模型历史（缓存 + 冻结）</td></tr><tr><td><strong>turn / step</strong></td><td>turn = 零或多个 step；step = 一次模型调用 + 其工具</td></tr><tr><td><strong>Agent</strong></td><td>活代理句柄：session、inbox、status、cancel/send/steer/inject</td></tr><tr><td><strong>inbox</strong></td><td>待办消息投影（next-turn / next-step 两条列表）</td></tr><tr><td><strong>steer / inject</strong></td><td>转向（最近 step 边界消费）/ 注入上下文（不唤醒）</td></tr><tr><td><strong>AgentCancelCause</strong></td><td>取消原因：user/parent/hook/disposed</td></tr><tr><td><strong>Scoped&lt;T&gt;</strong></td><td>按 agent 作用域过滤派发的事件载体</td></tr><tr><td><strong>initiator</strong></td><td>进程内异步调用链的发起者归属</td></tr></tbody></table><h2 id="扩展机制" tabindex="-1">扩展机制 <a class="header-anchor" href="#扩展机制" aria-label="Permalink to &quot;扩展机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>释义</th></tr></thead><tbody><tr><td><strong>defineTool</strong></td><td>类型化工具构造 DSL（schema + execute + render + present*）</td></tr><tr><td><strong>tools/pre-execute</strong></td><td>执行前策略 waterfall（权限/审批/沙箱）</td></tr><tr><td><strong>presentationMeta</strong></td><td>工具结果的可重放卡片数据（随 <code>tool/result</code> 持久化）</td></tr><tr><td><strong>Code Mode</strong></td><td>以代码表达操作的执行模式；复用同一受保护管道</td></tr><tr><td><strong>dynamic plugin</strong></td><td>会话内创建/审批/运行/更新/回滚的插件</td></tr><tr><td><strong>Package</strong></td><td>动态插件的不可变代码版本（packageId）</td></tr><tr><td><strong>Inspect Provider</strong></td><td>只读接口目录（Service/Event/Builtin/Slot/Theme/Tool）</td></tr><tr><td><strong>Slot</strong></td><td>客户端 UI 注册位（single/list/keyed/chain）</td></tr><tr><td><strong>@Remote</strong></td><td>Host 服务方法暴露给 Client 的生成式契约</td></tr><tr><td><strong>boot manifest（<strong>DSH_BOOT</strong>）</strong></td><td>注入页面的客户端插件入口图</td></tr></tbody></table>',9)])])}const b=d(s,[["render",n]]);export{p as __pageData,b as default};
